namespace ghidra.framework.main.datatable;



using docking.widgets.table;

public class DomainFileType : Comparable<DomainFileType>, DisplayStringProvider {
	private string contentType;
	private Icon icon;
	private bool isVersioned;

	public DomainFileType(string contentType, Icon icon, bool isVersioned) {
		this.contentType = contentType;
		this.icon = icon;
		this.isVersioned = isVersioned;
	}

	/* @Override */
	public int compareTo(DomainFileType other) {
		int result = contentType.compareTo(other.contentType);
		if (result == 0) {
			result = Boolean.valueOf(isVersioned).compareTo(Boolean.valueOf(other.isVersioned));
		}
		return result;
	}

	public Icon getIcon() {
		return icon;
	}

	/* @Override */
	public string getDisplayString() {
		return contentType;
	}

	/* @Override */
	public string toString() {
		return contentType + " (" + (isVersioned ? "versioned" : "unversioned") + ")";
	}
}
